    for name in names:
        # Replace hyphens with spaces
        name = name.replace('-', ' ')
        # Split the name into words
        words = name.split()
        if len(words) == 1:
            code = words[0][:4]
        elif len(words) == 2:
            code = words[0][:2] + words[1][:2]
        elif len(words) == 3:
            code = words[0][0] + words[1][0] + words[2][:2]
        elif len(words) == 4:
            code = words[0][0] + words[1][0] + words[2][0] + words[3][0]
        else:
            code = ''
        # Convert to uppercase
        code = code.upper()
        codes.append(code)
    return codes
